messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>3D Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x202025);
scene.fog = new THREE.Fog(0x202025, 10, 20);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 5);
camera.lookAt(0, 1, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(3, 5, 4);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(1024, 1024);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0xffaa00, 0.3, 10);
pointLight.position.set(-2, 3, 2);
scene.add(pointLight);

// --- Materials ---
const skinMat = new THREE.MeshStandardMaterial({ color: 0xd4a574, roughness: 0.7 });
const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366cc, roughness: 0.6 });
const pantsMat = new THREE.MeshStandardMaterial({ color: 0x222244, roughness: 0.6 });
const shoeMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4 });
const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });
const beltMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.5 });

// --- Humanoid Builder ---
function buildHumanoid() {
    const group = new THREE.Group();

    // Helper: box with rounded feel
    function box(w, h, d, mat) {
        const geo = new THREE.BoxGeometry(w, h, d);
        const mesh = new THREE.Mesh(geo, mat);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        return mesh;
    }

    // Torso
    const torso = box(0.45, 0.55, 0.25, shirtMat);
    torso.position.y = 1.25;
    group.add(torso);

    // Belt
    const belt = box(0.47, 0.06, 0.27, beltMat);
    belt.position.y = 0.98;
    group.add(belt);

    // Head
    const head = box(0.28, 0.30, 0.28, skinMat);
    head.position.y = 1.72;
    group.add(head);

    // Neck
    const neck = box(0.12, 0.10, 0.12, skinMat);
    neck.position.y = 1.53;
    group.add(neck);

    // Shoulder joint (left)
    const lShoulder = new THREE.Group();
    lShoulder.position.set(-0.30, 1.45, 0);
    group.add(lShoulder);
    const lUpperArm = box(0.12, 0.30, 0.12, shirtMat);
    lUpperArm.position.y = -0.15;
    lShoulder.add(lUpperArm);

    // Elbow joint (left)
    const lElbow = new THREE.Group();
    lElbow.position.set(0, -0.30, 0);
    lShoulder.add(lElbow);
    const lForearm = box(0.11, 0.28, 0.11, skinMat);
    lForearm.position.y = -0.14;
    lElbow.add(lForearm);

    // Hand (left)
    const lHand = box(0.10, 0.10, 0.08, skinMat);
    lHand.position.y = -0.30;
    lElbow.add(lHand);

    // Shoulder joint (right)
    const rShoulder = new THREE.Group();
    rShoulder.position.set(0.30, 1.45, 0);
    group.add(rShoulder);
    const rUpperArm = box(0.12, 0.30, 0.12, shirtMat);
    rUpperArm.position.y = -0.15;
    rShoulder.add(rUpperArm);

    // Elbow joint (right)
    const rElbow = new THREE.Group();
    rElbow.position.set(0, -0.30, 0);
    rShoulder.add(rElbow);
    const rForearm = box(0.11, 0.28, 0.11, skinMat);
    rForearm.position.y = -0.14;
    rElbow.add(rForearm);

    // Hand (right)
    const rHand = box(0.10, 0.10, 0.08, skinMat);
    rHand.position.y = -0.30;
    rElbow.add(rHand);

    // Hip joint (left)
    const lHip = new THREE.Group();
    lHip.position.set(-0.12, 0.95, 0);
    group.add(lHip);
    const lThigh = box(0.14, 0.38, 0.14, pantsMat);
    lThigh.position.y = -0.19;
    lHip.add(lThigh);

    // Knee joint (left)
    const lKnee = new THREE.Group();
    lKnee.position.set(0, -0.38, 0);
    lHip.add(lKnee);
    const lShin = box(0.12, 0.36, 0.12, pantsMat);
    lShin.position.y = -0.18;
    lKnee.add(lShin);

    // Foot (left)
    const lFoot = box(0.12, 0.08, 0.22, shoeMat);
    lFoot.position.set(0, -0.38, 0.05);
    lKnee.add(lFoot);

    // Hip joint (right)
    const rHip = new THREE.Group();
    rHip.position.set(0.12, 0.95, 0);
    group.add(rHip);
    const rThigh = box(0.14, 0.38, 0.14, pantsMat);
    rThigh.position.y = -0.19;
    rHip.add(rThigh);

    // Knee joint (right)
    const rKnee = new THREE.Group();
    rKnee.position.set(0, -0.38, 0);
    rHip.add(rKnee);
    const rShin = box(0.12, 0.36, 0.12, pantsMat);
    rShin.position.y = -0.18;
    rKnee.add(rShin);

    // Foot (right)
    const rFoot = box(0.12, 0.08, 0.22, shoeMat);
    rFoot.position.set(0, -0.38, 0.05);
    rKnee.add(rFoot);

    return {
        group, torso, head,
        lShoulder, lElbow, lHand,
        rShoulder, rElbow, rHand,
        lHip, lKnee, lFoot,
        rHip, rKnee, rFoot
    };
}

const human = buildHumanoid();
scene.add(human.group);

// --- Treadmill Ground ---
const groundGeo = new THREE.BoxGeometry(6, 0.1, 3);
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.position.y = -0.05;
ground.receiveShadow = true;
scene.add(ground);

// Treadmill belt lines
const beltGeo = new THREE.BoxGeometry(5.5, 0.01, 0.05);
const beltLineMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
for (let i = 0; i < 20; i++) {
    const line = new THREE.Mesh(beltGeo, beltLineMat);
    line.position.set(0, 0.01, -1.2 + i * 0.12);
    scene.add(line);
}

// Treadmill side rails
const railGeo = new THREE.BoxGeometry(0.05, 0.05, 2.8);
const railMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
const lRail = new THREE.Mesh(railGeo, railMat);
lRail.position.set(-3.05, 0.025, 0);
scene.add(lRail);
const rRail = new THREE.Mesh(railGeo, railMat);
rRail.position.set(3.05, 0.025, 0);
scene.add(rRail);

// --- Animation State ---
const TOTAL_CYCLE = 10; // seconds
const STAY_DURATION = 2;
const WALK_DURATION = 3;
const RUN_DURATION = 3;

// Phase boundaries (start time within cycle)
// 0.0 - 2.0: stand
// 2.0 - 5.0: walk
// 5.0 - 8.0: run
// 8.0 - 10.0: stand

// --- Animation Functions ---

function animateStanding(h, time) {
    // Reset all joint rotations
    const joints = ['lShoulder', 'lElbow', 'rShoulder', 'rElbow', 'lHip', 'lKnee', 'rHip', 'rKnee'];
    joints.forEach(name => {
        const j = h[name];
        j.rotation.x = 0;
        j.rotation.y = 0;
        j.rotation.z = 0;
    });
    // Slight natural sway
    h.torso.rotation.z = Math.sin(time * 1.5) * 0.01;
    h.head.rotation.z = Math.sin(time * 1.5 + 0.5) * 0.01;
}

function animateWalking(h, phase) {
    // phase: 0 to 1 within the walk cycle
    const speed = 1.5; // walking pace
    const angle = phase * Math.PI * 2 * speed;

    // Left leg
    h.lHip.rotation.x = Math.sin(angle) * 0.5;
    h.lKnee.rotation.x = Math.max(0, Math.sin(angle + 0.3)) * 0.8;

    // Right leg
    h.rHip.rotation.x = Math.sin(angle + Math.PI) * 0.5;
    h.rKnee.rotation.x = Math.max(0, Math.sin(angle + Math.PI + 0.3)) * 0.8;

    // Left arm (opposite to left leg)
    h.lShoulder.rotation.x = Math.sin(angle + Math.PI) * 0.4;
    h.lElbow.rotation.x = Math.max(0, Math.sin(angle + Math.PI + 0.5)) * 0.5;

    // Right arm (opposite to right leg)
    h.rShoulder.rotation.x = Math.sin(angle) * 0.4;
    h.rElbow.rotation.x = Math.max(0, Math.sin(angle + 0.5)) * 0.5;

    // Slight torso bob
    h.torso.position.y = 1.25 + Math.sin(angle * 2) * 0.01;
    h.torso.rotation.z = Math.sin(angle) * 0.02;
    h.head.rotation.z = Math.sin(angle) * 0.02;
}

function animateRunning(h, phase) {
    const speed = 3.5; // faster pace
    const angle = phase * Math.PI * 2 * speed;

    // Left leg - larger, more aggressive swings
    h.lHip.rotation.x = Math.sin(angle) * 0.9;
    h.lKnee.rotation.x = Math.max(0, Math.sin(angle + 0.2)) * 1.4; // more knee lift

    // Right leg - opposite
    h.rHip.rotation.x = Math.sin(angle + Math.PI) * 0.9;
    h.rKnee.rotation.x = Math.max(0, Math.sin(angle + Math.PI + 0.2)) * 1.4;

    // Left arm - larger swings
    h.lShoulder.rotation.x = Math.sin(angle + Math.PI) * 0.7;
    h.lElbow.rotation.x = Math.max(0, Math.sin(angle + Math.PI + 0.4)) * 1.2;

    // Right arm - opposite
    h.rShoulder.rotation.x = Math.sin(angle) * 0.7;
    h.rElbow.rotation.x = Math.max(0, Math.sin(angle + 0.4)) * 1.2;

    // Forward lean
    h.torso.rotation.z = -0.12;
    h.head.rotation.z = -0.05;

    // More pronounced bob
    h.torso.position.y = 1.25 + Math.abs(Math.sin(angle * 2)) * 0.03;

    // Slight forward translation
    h.group.position.x = -0.05;
}

function animateTransition(h, phase) {
    // Smooth blend: phase 0 = fully in old state, phase 1 = fully in new state
    const t = phase;
    const smooth = t * t * (3 - 2 * t); // smoothstep

    // We'll use this for transitions between phases
    return smooth;
}

// --- Main Loop ---
const clock = new THREE.Clock();

function animate() {
    requestAnimationFrame(animate);

    const elapsed = clock.getElapsedTime();
    const cycleTime = elapsed % TOTAL_CYCLE;

    // Determine phase
    let phase = 0;
    if (cycleTime < STAY_DURATION) {
        // Standing: 0 to 1
        phase = cycleTime / STAY_DURATION;
        animateStanding(human, cycleTime);
    } else if (cycleTime < STAY_DURATION + WALK_DURATION) {
        // Walking: 0 to 1
        const walkTime = cycleTime - STAY_DURATION;
        phase = walkTime / WALK_DURATION;
        animateWalking(human, phase);
    } else if (cycleTime < STAY_DURATION + WALK_DURATION + RUN_DURATION) {
        // Running: 0 to 1
        const runTime = cycleTime - STAY_DURATION - WALK_DURATION;
        phase = runTime / RUN_DURATION;
        animateRunning(human, phase);
    } else {
        // Standing again: 0 to 1
        const standTime = cycleTime - STAY_DURATION - WALK_DURATION - RUN_DURATION;
        phase = standTime / STAY_DURATION;
        animateStanding(human, standTime);
    }

    renderer.render(scene, camera);
}

animate();

// --- Resize ---
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

</script>
</body>
</html>
```
